INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00459-8d09-7d55-b50a-8fa02ef5fae0'::uuid, '019f9df7-a2a2-7877-afdf-c436930f3059'::uuid, 'Find the number of elements in A ∪ B, where A = {1, 4, 9} and B = {1, 2, 4, 8}.', '5', 'A ∪ B = {1, 2, 4, 8, 9}. There are 5 elements in the union.', 'Easy', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:36:12.809Z'::timestamptz, '2026-08-15T07:36:12.809Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00459-8d18-7bab-b5b9-15e664401ba9'::uuid, '019f9df7-a2a2-78c7-aa4b-565799c65ce4'::uuid, 'A function is given by s = (r - 3q) / q^2. Evaluate s when q = -3 and r = 5.', '14/9', 'Substitute q = -3 and r = 5 into s = (r - 3q) / q^2. Then s = (5 - 3(-3)) / (-3)^2 = 14/9.', 'Easy', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:36:12.824Z'::timestamptz, '2026-08-15T07:36:12.824Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00459-8d40-79b4-9dae-8b2e881edaba'::uuid, '019f9df7-a2a2-78da-b367-27466579928e'::uuid, 'Solve the inequality (2x + 1)/3 >= (3x - 1)/5.', 'x >= -8', 'Multiply both sides by 15: 5(2x + 1) >= 3(3x - 1). Expand: 10x + 5 >= 9x - 3. Subtract 9x: x + 5 >= -3. Subtract 5: x >= -8.', 'Medium', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:36:12.864Z'::timestamptz, '2026-08-15T07:36:12.864Z'::timestamptz) ON CONFLICT (id) DO NOTHING;